{
  "constraints": [
    {
      "constraint": "画面中必须出现可识别的雷克萨斯品牌标识元素：雷克萨斯徽标，或清晰可读的“LEXUS/雷克萨斯”文字标识。",
      "polarity": "must_have",
      "variants": [
        "雷克萨斯徽标",
        "LEXUS文字标识",
        "雷克萨斯文字标识"
      ],
      "source": "common_sense"
    },
    {
      "constraint": "画面中不得将雷克萨斯徽标绘制成圆形、盾形、方形、三角形或其他非椭圆外框。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "画面中不得将雷克萨斯徽标绘制成椭圆外框内不含字母L。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "画面中不得将雷克萨斯徽标绘制成水平镜像翻转、字母L反向的形态。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "画面中不得以其他汽车品牌标识（如丰田、奔驰、宝马、奥迪）替代雷克萨斯徽标或雷克萨斯文字标识。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    }
  ]
}
